window.FILM_WORK_PROMPTS={"work_id":"src-6bef086198911cf0","records":[{"work_id":"src-6bef086198911cf0","frame_id":"FG-dfe5030bc382957f","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/07 (22).jpg","source_page":"https://film-grab.com/2014/06/17/a-hitchhikers-guide-to-the-galaxy/","scene":"一名金发男子位于画面中央，身穿深红色大衣，内搭黑色高领衣物，佩戴黑色大框墨镜。背景为深蓝色夜空，左上方有一轮明月，周围环绕着稀疏的薄云。","analysis":"画面采用中心构图，人物占据画面中下部约三分之二的区域，仅可见头部及肩胸部。视角接近平视，人物面部受光均匀，与深蓝色背景形成强烈对比。左侧月亮发出柔和白光，照亮部分云层，整体色调偏冷，人物红色大衣在暗色环境中显得突出。","prompt":"画面中央是一名留着金色长卷发的男子，面部佩戴一副宽大的黑色方框墨镜，身穿深红色翻领大衣，领口处露出黑色高领内搭。背景是深邃的蓝色夜空，左上方悬挂着一轮明亮的圆月，月光周围散布着几缕灰白色的薄云。人物仅显示头部和肩胸部，占据画面主要位置，整体光线偏暗，冷色调背景与人物暖色衣物形成对比，营造出一种神秘且冷峻的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T12:33:09-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/07 (22).jpg","observed_dimensions":[1280,534],"source_thumbnail_dimensions":[500,209],"source_image_match_mae":0.488,"observed_resolution":"normal","observation_limits":[],"id":"VP-140d5b1f514ed64b","origin":"visual"},{"work_id":"src-6bef086198911cf0","frame_id":"FG-f4dd3d4804a0053e","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/20 (22).jpg","source_page":"https://film-grab.com/2014/06/17/a-hitchhikers-guide-to-the-galaxy/","scene":"前景左侧为穿着红白菱形格纹袜子的双腿，右侧坐着一个白色球形头部、绿色眼睛的小型机器人，背景是米色岩石墙面和一排奇异植物。","analysis":"画面采用低角度仰视拍摄，前景人物腿部占据左侧约三分之一画面，形成强烈的透视对比。右侧机器人全身可见，呈坐姿，体型较小。背景环境占据大部分空间，光线柔和明亮，整体色调偏暖白，营造出一种洁净、科幻的室内氛围。","prompt":"低角度仰视视角的科幻室内场景。前景左侧是人物的小腿和双脚，穿着米色底红色菱形格纹的针织短袜，皮肤白皙，腿部线条清晰。右侧中景处坐着一个白色小型机器人，头部为巨大的白色球体，面部有两条细长的绿色发光眼睛，身体圆润，四肢短小，双手握拳置于身前。背景是一面粗糙的米黄色岩石墙壁，墙前摆放着几株造型奇特的灰绿色植物，植物底部有微弱的光点。地面为光滑的浅色材质，整体光线均匀柔和，色彩以白色、米色和红色为主，具有强烈的未来主义风格。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T12:33:17-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/20 (22).jpg","observed_dimensions":[1280,534],"source_thumbnail_dimensions":[500,209],"source_image_match_mae":0.534,"observed_resolution":"normal","observation_limits":[],"id":"VP-8d0b712bce589885","origin":"visual"},{"work_id":"src-6bef086198911cf0","frame_id":"FG-2283e4288ee4387b","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/33 (22).jpg","source_page":"https://film-grab.com/2014/06/17/a-hitchhikers-guide-to-the-galaxy/","scene":"室内条纹墙面背景，左侧投射巨大人物剪影，右侧站立四人，其中两人持蓝色长条物，中间一人捂脸，旁立银色球状雕塑。","analysis":"画面左侧被巨大的黑色人物剪影占据，右侧为实际人物群像。右侧四人仅上半身可见，站立姿态，其中两人手持蓝色长条物体，中间一人低头用白色织物遮挡面部。背景为横向条纹墙面，光线昏暗，剪影与实体人物形成强烈虚实对比，银色球状物在右侧反光。","prompt":"昏暗室内场景，背景为米色与褐色相间的横向条纹墙面。画面左侧占据约三分之二区域的是一个巨大的人物黑色剪影，轮廓显示为站立姿态，头部与肩部清晰。画面右侧站立着四个人物，仅上半身可见：最左侧与最右侧两人身穿绿色连帽长袍，手持蓝色长条状物体；中间偏左一人穿深色上衣，低头用白色织物捂住口鼻；中间偏右一人穿浅色衬衫。右侧人物旁立有一个银色金属质感的球状雕塑，表面有凹凸纹理。整体光线昏暗，左侧剪影浓重，右侧人物受光较弱，色调偏暖黄。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T12:33:24-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/33 (22).jpg","observed_dimensions":[1280,534],"source_thumbnail_dimensions":[500,209],"source_image_match_mae":0.473,"observed_resolution":"normal","observation_limits":[],"id":"VP-8276eb7b2e4b3705","origin":"visual"},{"work_id":"src-6bef086198911cf0","frame_id":"FG-1fe94b6cf6e07368","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/46 (21).jpg","source_page":"https://film-grab.com/2014/06/17/a-hitchhikers-guide-to-the-galaxy/","scene":"两个身影背对镜头坐在巨大的环形金属结构内部，面向远方地平线。背景是红橙色天空与低垂云层，地面覆盖着灰白色物质，两侧可见机械支架结构。","analysis":"环形结构占据画面中心，形成天然画框。左侧人物呈深色轮廓，右侧人物头部为球形，身体有黑白几何图案。两人均仅见上半身背影，坐姿低矮。视角平视略低，前景环形结构处于阴影中，背景天空明亮，形成强烈明暗对比。光线从地平线处透出，呈放射状，天空由橙黄过渡至深红，云层厚重。","prompt":"两个背影人物坐在巨大的圆形金属管道内部，管道内壁粗糙，顶部悬挂着冰凌状物体。左侧人物穿着深色衣物，右侧人物头部为光滑球形，身体穿着黑白相间的几何图案服装。两人面向远方，地平线处太阳低垂，放射出金色光芒。天空呈现深红与橙黄色调，云层厚重且层次分明。地面覆盖灰白色沙土或雪状物质，管道两侧延伸出机械臂状结构，带有金属关节和支架。前景环形结构处于暗部，背景天空明亮，整体色调偏暖，红橙色主导，具有科幻荒原氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T12:33:33-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/46 (21).jpg","observed_dimensions":[1280,534],"source_thumbnail_dimensions":[500,209],"source_image_match_mae":0.535,"observed_resolution":"normal","observation_limits":[],"id":"VP-58a46a8ee09c327a","origin":"visual"},{"work_id":"src-6bef086198911cf0","frame_id":"FG-75e2c7312acdae16","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/59 (20).jpg","source_page":"https://film-grab.com/2014/06/17/a-hitchhikers-guide-to-the-galaxy/","scene":"前景四名人物背对镜头站立，中景白色栅栏后排列着大量深色装甲生物，左侧有一个白色球形机器人，背景为绿色草地与灌木。","analysis":"画面采用过肩视角，前景四人仅见头部与肩背，占据画面下方约三分之一。中景白色栅栏横贯画面，将前景人物与后方密集的深色装甲生物群隔开。光线明亮，阳光从左侧照射，在草地上投下清晰阴影，色彩以绿色草地、白色栅栏和深色生物为主。","prompt":"过肩视角，前景四名人物背对镜头站立，仅可见头部与肩背，从左至右分别为短发深色皮肤人物、金色长发人物、红棕色短发人物及深色长发人物。中景一道白色木栅栏横贯画面，栅栏左侧站立一个白色球形机器人。栅栏后方密集排列着大量深色装甲生物，它们体型庞大，头部呈圆顶状，面部有金属质感，整齐列队。背景是起伏的绿色草地与修剪整齐的灌木丛。阳光从左侧照射，草地呈现鲜亮绿色，人物与生物投下清晰阴影，画面色彩对比鲜明，景深清晰。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T12:33:40-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/59 (20).jpg","observed_dimensions":[1280,534],"source_thumbnail_dimensions":[500,209],"source_image_match_mae":0.541,"observed_resolution":"normal","observation_limits":[],"id":"VP-b4ba33c319c9e8c8","origin":"visual"}]};